use super::ResolvedLang;

#[inline]
fn pick(
    lang: ResolvedLang,
    el: &'static str,
    fr: &'static str,
    es: &'static str,
    nl: &'static str,
    it: &'static str,
) -> Option<&'static str> {
    Some(match lang {
        ResolvedLang::El => el,
        ResolvedLang::Fr => fr,
        ResolvedLang::Es => es,
        ResolvedLang::Nl => nl,
        ResolvedLang::It => it,
        _ => return None,
    })
}

